//! `calc`: evaluate one 64-bit signed integer expression per input line.
//!
//! ```text
//! expr    := term    (('+' | '-') term)*
//! term    := unary   (('*' | '/' | '%') unary)*
//! unary   := '-' unary | primary
//! primary := NUMBER | '(' expr ')'
//! ```
//!
//! Evaluation uses an operator-precedence (shunting-yard) parser with explicit
//! stacks, so arbitrarily deep nesting cannot overflow the call stack.

use std::io::{self, Write};

pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    let mut evaluator = Evaluator::default();
    for line in input.split(|&b| b == b'\n') {
        if line.iter().all(|&b| b == b' ' || b == b'\t') {
            continue;
        }
        match evaluator.eval(line) {
            Ok(value) => writeln!(out, "{value}")?,
            Err(_) => out.write_all(b"error\n")?,
        }
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    Syntax,
    DivisionByZero,
    Overflow,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Neg,
    /// An open parenthesis; only ever lives on the operator stack.
    Open,
}

impl Op {
    fn binary(byte: u8) -> Option<Self> {
        Some(match byte {
            b'+' => Self::Add,
            b'-' => Self::Sub,
            b'*' => Self::Mul,
            b'/' => Self::Div,
            b'%' => Self::Rem,
            _ => return None,
        })
    }

    fn precedence(self) -> u8 {
        match self {
            Self::Open => 0,
            Self::Add | Self::Sub => 1,
            Self::Mul | Self::Div | Self::Rem => 2,
            Self::Neg => 3,
        }
    }
}

/// Reusable evaluation state; the stacks keep their allocations across lines.
#[derive(Default)]
pub struct Evaluator {
    values: Vec<i64>,
    ops: Vec<Op>,
}

impl Evaluator {
    pub fn eval(&mut self, line: &[u8]) -> Result<i64, Error> {
        self.values.clear();
        self.ops.clear();

        // `true` when the grammar requires an operand next (start, after an operator or '(').
        let mut expect_operand = true;
        let mut i = 0;
        while i < line.len() {
            let byte = line[i];
            match byte {
                b' ' | b'\t' => i += 1,
                b'0'..=b'9' if expect_operand => {
                    let len = line[i..]
                        .iter()
                        .position(|b| !b.is_ascii_digit())
                        .unwrap_or(line.len() - i);
                    self.values.push(parse_number(&line[i..i + len])?);
                    i += len;
                    expect_operand = false;
                }
                b'-' if expect_operand => {
                    self.ops.push(Op::Neg);
                    i += 1;
                }
                b'(' if expect_operand => {
                    self.ops.push(Op::Open);
                    i += 1;
                }
                b')' if !expect_operand => {
                    loop {
                        match self.ops.pop() {
                            Some(Op::Open) => break,
                            Some(op) => self.apply(op)?,
                            None => return Err(Error::Syntax),
                        }
                    }
                    i += 1;
                }
                _ if !expect_operand => {
                    let op = Op::binary(byte).ok_or(Error::Syntax)?;
                    // Left associativity: reduce everything that binds at least as tightly.
                    while let Some(&top) = self.ops.last()
                        && top.precedence() >= op.precedence()
                    {
                        self.ops.pop();
                        self.apply(top)?;
                    }
                    self.ops.push(op);
                    i += 1;
                    expect_operand = true;
                }
                _ => return Err(Error::Syntax),
            }
        }

        if expect_operand {
            return Err(Error::Syntax);
        }
        while let Some(op) = self.ops.pop() {
            if op == Op::Open {
                return Err(Error::Syntax);
            }
            self.apply(op)?;
        }
        match self.values[..] {
            [value] => Ok(value),
            _ => Err(Error::Syntax),
        }
    }

    fn apply(&mut self, op: Op) -> Result<(), Error> {
        let rhs = self.values.pop().ok_or(Error::Syntax)?;
        let result = if op == Op::Neg {
            rhs.checked_neg().ok_or(Error::Overflow)?
        } else {
            let lhs = self.values.pop().ok_or(Error::Syntax)?;
            binary(op, lhs, rhs)?
        };
        self.values.push(result);
        Ok(())
    }
}

fn binary(op: Op, lhs: i64, rhs: i64) -> Result<i64, Error> {
    match op {
        Op::Add => lhs.checked_add(rhs).ok_or(Error::Overflow),
        Op::Sub => lhs.checked_sub(rhs).ok_or(Error::Overflow),
        Op::Mul => lhs.checked_mul(rhs).ok_or(Error::Overflow),
        Op::Div if rhs == 0 => Err(Error::DivisionByZero),
        Op::Div => lhs.checked_div(rhs).ok_or(Error::Overflow),
        Op::Rem if rhs == 0 => Err(Error::DivisionByZero),
        // `i64::MIN % -1` is mathematically 0; only the quotient overflows.
        Op::Rem => Ok(lhs.wrapping_rem(rhs)),
        Op::Neg | Op::Open => unreachable!("{op:?} is not a binary operator"),
    }
}

fn parse_number(digits: &[u8]) -> Result<i64, Error> {
    digits.iter().try_fold(0i64, |acc, &d| {
        acc.checked_mul(10)
            .and_then(|acc| acc.checked_add(i64::from(d - b'0')))
            .ok_or(Error::Overflow)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(line: &str) -> Result<i64, Error> {
        Evaluator::default().eval(line.as_bytes())
    }

    #[test]
    fn precedence_and_associativity() {
        assert_eq!(eval("1 + 2 * 3"), Ok(7));
        assert_eq!(eval("(1 + 2) * 3"), Ok(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Ok(5));
        assert_eq!(eval("10 - 4 - 3"), Ok(3));
        assert_eq!(eval("100 / 10 / 5"), Ok(2));
        assert_eq!(eval("2*(3+4)*5"), Ok(70));
    }

    #[test]
    fn unary_minus() {
        assert_eq!(eval("--5"), Ok(5));
        assert_eq!(eval("2 * -3"), Ok(-6));
        assert_eq!(eval("1 - -2"), Ok(3));
        assert_eq!(eval("-(2 + 3)"), Ok(-5));
        assert_eq!(eval("-2 * 3"), Ok(-6));
        assert_eq!(eval("- 7 % 3"), Ok(-1));
    }

    #[test]
    fn division_semantics() {
        assert_eq!(eval("-7 / 2"), Ok(-3));
        assert_eq!(eval("-7 % 3"), Ok(-1));
        assert_eq!(eval("7 % -3"), Ok(1));
        assert_eq!(eval("1 / 0"), Err(Error::DivisionByZero));
        assert_eq!(eval("5 % 0"), Err(Error::DivisionByZero));
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Ok(0));
        assert_eq!(
            eval("(-9223372036854775807 - 1) / -1"),
            Err(Error::Overflow)
        );
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807"), Ok(i64::MAX));
        assert_eq!(eval("9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("-9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("9223372036854775807 + 1"), Err(Error::Overflow));
        assert_eq!(eval("-(-9223372036854775807 - 1)"), Err(Error::Overflow));
        assert_eq!(eval("3037000500 * 3037000500"), Err(Error::Overflow));
        assert_eq!(eval("000000000000000000000000001"), Ok(1));
    }

    #[test]
    fn syntax_errors() {
        for line in [
            "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")(", "1 -", "1 * * 2", "1 (2)",
            "(1)2", "1 x",
        ] {
            assert_eq!(eval(line), Err(Error::Syntax), "{line:?}");
        }
    }

    #[test]
    fn deep_nesting() {
        let depth = 200_000;
        let line = format!("{}1{}", "(-".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&line), Ok(1));
    }

    #[test]
    fn blank_lines_print_nothing() {
        let mut out = Vec::new();
        run(b"\n  42  \n\t\n1+1\n1/0", &mut out).unwrap();
        assert_eq!(out, b"42\n2\nerror\n");
    }
}

//! A small, fast, non-cryptographic hasher (the "Fx" hash used inside rustc,
//! plus an avalanche finalizer).
//!
//! The inputs hashed here (words, cache keys) are short byte strings, for which
//! the standard library's DoS-resistant SipHash is needlessly slow.

use std::hash::{BuildHasherDefault, Hasher};

const SEED: u64 = 0x51_7c_c1_b7_27_22_0a_95;

#[derive(Default, Clone, Copy)]
pub struct FxHasher {
    hash: u64,
}

impl FxHasher {
    #[inline]
    fn add(&mut self, word: u64) {
        self.hash = (self.hash.rotate_left(5) ^ word).wrapping_mul(SEED);
    }
}

impl Hasher for FxHasher {
    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        let mut chunks = bytes.chunks_exact(8);
        for chunk in &mut chunks {
            self.add(u64::from_le_bytes(
                chunk.try_into().expect("chunk of 8 bytes"),
            ));
        }
        let rest = chunks.remainder();
        if !rest.is_empty() {
            let mut buf = [0u8; 8];
            buf[..rest.len()].copy_from_slice(rest);
            self.add(u64::from_le_bytes(buf));
        }
    }

    #[inline]
    fn write_u8(&mut self, i: u8) {
        self.add(u64::from(i));
    }

    #[inline]
    fn write_usize(&mut self, i: usize) {
        self.add(i as u64);
    }

    /// Multiplication only propagates entropy upwards, so the low bits (which
    /// pick the hash table bucket) would depend only on the first bytes of each
    /// chunk. A final avalanche step (from MurmurHash3's `fmix64`) spreads them.
    #[inline]
    fn finish(&self) -> u64 {
        let mut h = self.hash;
        h ^= h >> 33;
        h = h.wrapping_mul(0xff51_afd7_ed55_8ccd);
        h ^= h >> 33;
        h
    }
}

pub type FxBuildHasher = BuildHasherDefault<FxHasher>;
pub type FxHashMap<K, V> = std::collections::HashMap<K, V, FxBuildHasher>;

//! `lru`: simulate a least-recently-used cache driven by text commands.
//!
//! Entries live in a slab (`Vec<Node>`) threaded by an intrusive doubly linked
//! list ordered from most to least recently used; a hash map indexes the slab
//! by key. Every command is O(1) expected time.

use std::io::{self, Write};

use crate::fxhash::FxHashMap;

pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    let mut lines = input.split(|&b| b == b'\n').map(trim_cr);
    let Some(capacity) = lines.next().and_then(parse_capacity) else {
        return Ok(());
    };
    let mut cache = LruCache::new(capacity);

    for line in lines {
        let mut tokens = line.split(|&b| b == b' ').filter(|t| !t.is_empty());
        match (tokens.next(), tokens.next(), tokens.next()) {
            (Some(b"SET"), Some(key), Some(value)) => cache.set(key, value),
            (Some(b"GET"), Some(key), _) => {
                out.write_all(cache.get(key).unwrap_or(b"NULL"))?;
                out.write_all(b"\n")?;
            }
            (Some(b"DEL"), Some(key), _) => {
                out.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
            }
            (Some(b"SIZE"), _, _) => {
                out.write_all(cache.len().to_string().as_bytes())?;
                out.write_all(b"\n")?;
            }
            // Blank or malformed lines have no effect.
            _ => {}
        }
    }
    Ok(())
}

fn trim_cr(line: &[u8]) -> &[u8] {
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn parse_capacity(line: &[u8]) -> Option<usize> {
    std::str::from_utf8(line)
        .ok()?
        .trim()
        .parse()
        .ok()
        .filter(|&c| c >= 1)
}

/// Sentinel index meaning "no node".
const NIL: usize = usize::MAX;

struct Node {
    key: Box<[u8]>,
    value: Box<[u8]>,
    prev: usize,
    next: usize,
}

pub struct LruCache {
    capacity: usize,
    index: FxHashMap<Box<[u8]>, usize>,
    nodes: Vec<Node>,
    /// Slab slots released by deletions, available for reuse.
    free: Vec<usize>,
    /// Most recently used node.
    head: usize,
    /// Least recently used node.
    tail: usize,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity >= 1, "LRU capacity must be at least 1");
        Self {
            capacity,
            index: FxHashMap::default(),
            nodes: Vec::new(),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    pub fn len(&self) -> usize {
        self.index.len()
    }

    pub fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let id = *self.index.get(key)?;
        self.promote(id);
        Some(&self.nodes[id].value)
    }

    pub fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&id) = self.index.get(key) {
            self.nodes[id].value = value.into();
            self.promote(id);
            return;
        }

        if self.len() == self.capacity {
            self.evict_lru();
        }
        let node = Node {
            key: key.into(),
            value: value.into(),
            prev: NIL,
            next: NIL,
        };
        let id = match self.free.pop() {
            Some(id) => {
                self.nodes[id] = node;
                id
            }
            None => {
                self.nodes.push(node);
                self.nodes.len() - 1
            }
        };
        self.index.insert(key.into(), id);
        self.push_front(id);
    }

    /// Removes `key`, returning whether it was present.
    pub fn remove(&mut self, key: &[u8]) -> bool {
        let Some(id) = self.index.remove(key) else {
            return false;
        };
        self.release(id);
        true
    }

    fn evict_lru(&mut self) {
        let id = self.tail;
        debug_assert_ne!(id, NIL, "evicting from an empty cache");
        self.index.remove(&self.nodes[id].key);
        self.release(id);
    }

    /// Unlinks node `id` and returns its slot to the free list.
    fn release(&mut self, id: usize) {
        self.unlink(id);
        let node = &mut self.nodes[id];
        node.key = Box::default();
        node.value = Box::default();
        self.free.push(id);
    }

    fn promote(&mut self, id: usize) {
        if self.head != id {
            self.unlink(id);
            self.push_front(id);
        }
    }

    fn unlink(&mut self, id: usize) {
        let Node { prev, next, .. } = self.nodes[id];
        match prev {
            NIL => self.head = next,
            p => self.nodes[p].next = next,
        }
        match next {
            NIL => self.tail = prev,
            n => self.nodes[n].prev = prev,
        }
    }

    fn push_front(&mut self, id: usize) {
        let old_head = self.head;
        let node = &mut self.nodes[id];
        node.prev = NIL;
        node.next = old_head;
        match old_head {
            NIL => self.tail = id,
            h => self.nodes[h].prev = id,
        }
        self.head = id;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            render("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n"),
            "1\nNULL\n2\n"
        );
    }

    #[test]
    fn overwrite_refreshes_recency() {
        assert_eq!(
            render("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c"),
            "9\nNULL\n3\n"
        );
    }

    #[test]
    fn delete_and_reuse_slots() {
        assert_eq!(
            render(
                "2\nSET x 1\nDEL x\nDEL x\nSIZE\nSET y 2\nSET z 3\nSET w 4\nGET y\nGET z\nGET w\nSIZE\n"
            ),
            "1\n0\n0\nNULL\n3\n4\n2\n"
        );
    }

    #[test]
    fn capacity_one() {
        assert_eq!(
            render("1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n"),
            "NULL\n2\n1\n"
        );
    }
}

//! `suite`: a command-line program bundling three independent stdin/stdout tools.
//!
//! - `wordfreq`: the ten most frequent ASCII words.
//! - `lru`: an LRU cache simulator.
//! - `calc`: a 64-bit signed integer expression evaluator.

mod calc;
mod fxhash;
mod lru;
mod wordfreq;

use std::io::{self, BufWriter, Read, Write};
use std::process::ExitCode;

const USAGE: &str = "usage: app <wordfreq|lru|calc>  (reads standard input)";

type Command = fn(&[u8], &mut dyn Write) -> io::Result<()>;

fn main() -> ExitCode {
    let Some(name) = std::env::args().nth(1) else {
        eprintln!("{USAGE}");
        return ExitCode::from(2);
    };
    let command: Command = match name.as_str() {
        "wordfreq" => wordfreq::run,
        "lru" => lru::run,
        "calc" => calc::run,
        other => {
            eprintln!("unknown subcommand `{other}`\n{USAGE}");
            return ExitCode::from(2);
        }
    };

    match execute(command) {
        Ok(()) => ExitCode::SUCCESS,
        // A closed stdout (e.g. piping into `head`) is not a failure worth reporting.
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("app {name}: {e}");
            ExitCode::FAILURE
        }
    }
}

fn execute(command: Command) -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;
    let mut out = BufWriter::with_capacity(1 << 16, io::stdout().lock());
    command(&input, &mut out)?;
    out.flush()
}

//! `wordfreq`: print the ten most frequent words of the input.
//!
//! A word is a maximal run of ASCII letters, folded to lowercase; every other
//! byte is a separator.

use std::io::{self, Write};

use crate::fxhash::FxHashMap;

const TOP: usize = 10;

pub fn run(input: &[u8], out: &mut dyn Write) -> io::Result<()> {
    for (word, count) in top_words(input, TOP) {
        out.write_all(count.to_string().as_bytes())?;
        out.write_all(b" ")?;
        out.write_all(&word)?;
        out.write_all(b"\n")?;
    }
    Ok(())
}

/// Counts every word in `input` (lowercased).
fn count_words(input: &[u8]) -> FxHashMap<Box<[u8]>, u64> {
    let mut counts: FxHashMap<Box<[u8]>, u64> = FxHashMap::default();
    let mut word = Vec::with_capacity(64);
    let mut rest = input;

    while let Some(start) = rest.iter().position(u8::is_ascii_alphabetic) {
        rest = &rest[start..];
        let len = rest
            .iter()
            .position(|b| !b.is_ascii_alphabetic())
            .unwrap_or(rest.len());
        let (raw, tail) = rest.split_at(len);
        rest = tail;

        word.clear();
        word.extend(raw.iter().map(u8::to_ascii_lowercase));
        // Look up by slice first so that repeated words never allocate.
        match counts.get_mut(word.as_slice()) {
            Some(count) => *count += 1,
            None => {
                counts.insert(word.as_slice().into(), 1);
            }
        }
    }
    counts
}

/// The `n` most frequent words, by count descending then word ascending.
fn top_words(input: &[u8], n: usize) -> Vec<(Box<[u8]>, u64)> {
    let mut entries: Vec<_> = count_words(input).into_iter().collect();
    let order =
        |a: &(Box<[u8]>, u64), b: &(Box<[u8]>, u64)| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0));
    if entries.len() > n {
        entries.select_nth_unstable_by(n, order);
        entries.truncate(n);
    }
    entries.sort_unstable_by(order);
    entries
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(input: &[u8]) -> String {
        let mut out = Vec::new();
        run(input, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            render(b"The cat and the hat."),
            "2 the\n1 and\n1 cat\n1 hat\n"
        );
    }

    #[test]
    fn separators_and_invalid_utf8() {
        assert_eq!(
            render(b"don't\xffstop_me 4now,\xc3(now-NOW"),
            "3 now\n1 don\n1 me\n1 stop\n1 t\n"
        );
    }

    #[test]
    fn empty_and_no_words() {
        assert_eq!(render(b""), "");
        assert_eq!(render(b"123 _ !!"), "");
    }

    #[test]
    fn at_most_ten_with_ties() {
        let input = b"l k j i h g f e d c b a a";
        assert_eq!(
            render(input),
            "2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"
        );
    }
}
